(function(){"use strict";self.onmessage=i=>{const{action:s,chunkX:t,chunkZ:o,chunkSize:e=100}=i.data;if(s==="loadChunk"){const d=performance.now(),c=[],h=4;for(let n=0;n<h;n++){const f=(n%2===0?-1:1)*25+t*e,l=(n<2?-1:1)*25+o*e,a=15+Math.abs(Math.sin(t*13+o*7+n))*35;c.push({id:`${t}_${o}_b${n}`,x:f,y:a/2,z:l,width:18,height:a,depth:20,color:n%2===0?"#dcdde1":"#f5f6fa"})}const u=performance.now();self.postMessage({action:"chunkLoaded",chunkX:t,chunkZ:o,buildings:c,generationTimeMs:u-d})}else s==="unloadChunk"&&self.postMessage({action:"chunkUnloaded",chunkX:t,chunkZ:o})}})();
